package controller;
import dao.VendorDAO; import model.Vendor; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*;
public class VendorLoginServlet extends HttpServlet {protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String e=req.getParameter("email"),p=req.getParameter("password");try{Vendor v=new VendorDAO().login(e,p);if(v!=null){HttpSession s=req.getSession(true);s.setAttribute("vendorLoggedIn",true);s.setAttribute("vendorId",v.getVendorId());s.setAttribute("vendorName",v.getVendorName());s.setAttribute("vendorEmail",v.getEmail());s.setAttribute("role","VENDOR");resp.sendRedirect(req.getContextPath()+"/VendorDashboardServlet");}else{req.setAttribute("error","Invalid vendor email/password or inactive vendor.");req.getRequestDispatcher("/vendorLogin.jsp").forward(req,resp);}}catch(Exception ex){throw new ServletException(ex);}}}